1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Tags\Models;
6	
7	use AtrioTeam\DigitalHub\Identity\Concerns\HasMetadata;
8	use Illuminate\Database\Eloquent\Relations\BelongsTo;
9	use Spatie\Tags\Tag as SpatieTag;
10	
11	/**
12	 * Tag esteso da spatie/laravel-tags.
13	 *
14	 * Il campo `type` nativo di spatie è ignorato: la categoria del tag è una FK
15	 * verso un modello vero (`TagCategory`), così da avere id stabile e nome
16	 * translatable per il recupero dal frontend.
17	 *
18	 * @property int|null $tag_category_id
19	 * @property string|null $color colore facoltativo (hex #RRGGBB)
20	 */
21	class Tag extends SpatieTag
22	{
23	    use HasMetadata;
24	
25	    /**
26	     * @return BelongsTo<TagCategory, $this>
27	     */
28	    public function category(): BelongsTo
29	    {
30	        return $this->belongsTo(TagCategory::class, 'tag_category_id');
31	    }
32	}
