1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace AtrioTeam\DigitalHub\Identity\Concerns;
6	
7	use AtrioTeam\DigitalHub\Metadata\Models\Metadata;
8	use Illuminate\Database\Eloquent\Model;
9	use Illuminate\Database\Eloquent\Relations\MorphMany;
10	
11	/**
12	 * Aggiunge la gestione manuale di metadati chiave/valore a un modello.
13	 *
14	 * Storage polimorfico su un'unica tabella `metadata` (vedi {@see Metadata}):
15	 * abilitare i metadati su un nuovo modello = solo `use HasMetadata;`, nessuna
16	 * migration aggiuntiva. Chiavi libere. Interrogabile via la relazione
17	 * `metadata()` (es. filtro tabella {@see MetadataFilter}).
18	 *
19	 * @property-read \Illuminate\Database\Eloquent\Collection<int, Metadata> $metadata
20	 *
21	 * @mixin Model
22	 */
23	trait HasMetadata
24	{
25	    /**
26	     * @return MorphMany<Metadata, $this>
27	     */
28	    public function metadata(): MorphMany
29	    {
30	        return $this->morphMany(Metadata::class, 'metadatable')->orderBy('sort');
31	    }
32	
33	    /**
34	     * Valore del metadato per la chiave data, o null se assente.
35	     */
36	    public function getMeta(string $key): ?string
37	    {
38	        return $this->metadata->firstWhere('key', $key)?->value;
39	    }
40	
41	    /**
42	     * Imposta (o aggiorna) il valore per una chiave. Persiste subito.
43	     */
44	    public function setMeta(string $key, ?string $value): Metadata
45	    {
46	        /** @var Metadata $meta */
47	        $meta = $this->metadata()->updateOrCreate(
48	            ['key' => $key],
49	            ['value' => $value],
50	        );
51	
52	        // invalida la relazione in cache così getMeta() rilegge aggiornato
53	        $this->unsetRelation('metadata');
54	
55	        return $meta;
56	    }
57	
58	    /**
59	     * Rimuove il metadato per la chiave data. Ritorna il numero di righe eliminate.
60	     */
61	    public function forgetMeta(string $key): int
62	    {
63	        /** @var int $deleted */
64	        $deleted = $this->metadata()->where('key', $key)->delete();
65	
66	        $this->unsetRelation('metadata');
67	
68	        return $deleted;
69	    }
70	
71	    /**
72	     * Tutti i metadati come mappa chiave => valore.
73	     *
74	     * @return array<string, string|null>
75	     */
76	    public function metaArray(): array
77	    {
78	        /** @var array<string, string|null> $map */
79	        $map = $this->metadata->pluck('value', 'key')->all();
80	
81	        return $map;
82	    }
83	}
