docker compose exec -T php php artisan tinker --execute="
use AtrioTeam\DigitalHub\Metadata\Models\Metadata;
\$rows = Metadata::where('key','info_prodotto:finalita')->get(['metadatable_type','metadatable_id','key','value']);
echo \$rows->count().\" rows\n\";
foreach(\$rows as \$r){ echo \$r->metadatable_type.' #'.\$r->metadatable_id.' = '.\$r->value.PHP_EOL; }
" 2>&1 | tail -40

