9	use Illuminate\Database\Eloquent\Builder;
10	
11	/**
12	 * Filtro tabella riutilizzabile per i metadati manuali (chiave e/o valore).
13	 * Da aggiungere alle Table dei modelli che usano il trait
14	 * {@see \AtrioTeam\DigitalHub\Identity\Concerns\HasMetadata}:
15	 *
16	 *     ->filters([ MetadataFilter::make() ])
17	 *
18	 * Filtra via `whereHas('metadata', ...)`: la chiave sfrutta l'index dedicato,
19	 * il valore restringe con un LIKE sul sottoinsieme già filtrato per chiave.
20	 */
21	class MetadataFilter
22	{
23	    public static function make(string $name = 'metadata'): Filter
24	    {
25	        return Filter::make($name)
26	            ->schema([
27	                TextInput::make('key')
28	                    ->label(__('digital-hub::metadata.fields.key')),
29	                TextInput::make('value')
30	                    ->label(__('digital-hub::metadata.fields.value')),
31	            ])
32	            ->query(function (Builder $query, array $data): Builder {
33	                $key = is_string($data['key'] ?? null) && $data['key'] !== '' ? $data['key'] : null;
34	                $value = is_string($data['value'] ?? null) && $data['value'] !== '' ? $data['value'] : null;
35	
36	                if ($key === null && $value === null) {
37	                    return $query;
38	                }
39	
40	                return $query->whereHas('metadata', function (Builder $q) use ($key, $value): void {
41	                    if ($key !== null) {
42	                        $q->where('key', $key);
43	                    }
44	                    if ($value !== null) {
45	                        $q->where('value', 'like', "%{$value}%");
46	                    }
47	                });
48	            })
49	            ->indicateUsing(function (array $data): ?string {
50	                $parts = [];
51	                if (is_string($data['key'] ?? null) && $data['key'] !== '') {
52	                    $parts[] = __('digital-hub::metadata.fields.key') . ': ' . $data['key'];
53	                }
54	                if (is_string($data['value'] ?? null) && $data['value'] !== '') {
55	                    $parts[] = __('digital-hub::metadata.fields.value') . ': ' . $data['value'];
56	                }
57	
58	                return $parts === [] ? null : implode(' · ', $parts);
59	            });
60	    }
61	}
